        "四、公司法第214條：繼續6個月以上、持有1%以上股份之股東，得以書面請求監察人為公司對董事提起訴訟；監察人30日內不提起時，丁得為公司提起代表訴訟。第245條：繼續6個月以上、持有1%以上股份之股東，得檢附理由與事證聲請法院選派檢查人。丁符合1%門檻，若已滿6個月即可行使。",
