      "year": 107,
      "session": 4,
      "subject": "law",
      "number": 1,
      "stem": "A 公司與 B 公司均為非公開發行股票之公司，A 公司實收資本額為新臺幣(以下同)2 億元，已 發行有表決權股份總數 2,000 萬股。B 公司之實收資本額則為 1 億元，已發行有表決權股份總 數 1,000 萬股，設有 5 席董事，2 席監察人。A 公司基於策略聯盟之考量，持有 B 公司 400 萬 股之股份，並指派甲、乙二人為代表人，當選 B 公司之董事，甲並被推選為 B 公司之董事長。試依現行公司法回答下列問題，並評論之：(1) A 公司為擴大留才之對象，可否於章程中規定，於股東會決議對員工發行限制員工權利新 股時，其發行對象包括 B 公司之員工？（5 分） (2) 又 B 公司可否於章程中規定，以獲利狀況之定額或比率，分派員工酬勞時，包括 A 公司之 員工？（5 分）",
      "sourceIds": [
        "law-02"
      ],
