      "session": 1,
      "subject": "law",
      "number": 1,
      "stem": "為強化洗錢防制，增加公司實質受益人的透明度，2018 年公司法新增第 22 條之 1 規定，要求公 司申報特定人姓名、國籍等相關資料。請問A 股份有限公司有設有董事三人，分別為：自然人甲、 自然人乙，與B 股份有限公司 (B 公司係由丙和丁兩位自然人共同出資設立)，監察人自然人戊；另外，C基金會(C基金會係由己捐助設立)與D境外公司分別持有A公司已發行股份總數8% 與15%。請問依據新增公司法第22 條之 1 規定，A 公司每年應定期申報上述何人之姓名、國籍等法律要求 之資料？(10 分)",
