      "year": 108,
      "session": 2,
      "subject": "law",
      "number": 2,
      "stem": "A 上櫃公司（下稱 A 公司）董事會有三席獨立董事四席一般董事，設置審計委員會。A 公司董 事擬購置房屋一棟，作為主營業所。A 公司董事長個人甲知悉 B 公司欲出售其所有位於新莊副 都心之商辦大樓，地點適宜，交易金額約新台幣 5 億元，占 A 公司實收資本 10%，於是準備與 B 公司進行該房屋買賣。乙為甲之配偶，同時也是 B 公司董事長。請說明 A 公司應完成哪些程 序，始得與 B 公司進行房屋買賣。（10 分）",
