      "year": 108,
      "session": 3,
      "subject": "law",
      "number": 2,
      "stem": "相較於公司法的董事、監察人資格限制，請說明證券交易法對公開發行公司之董事 (非獨 立董事)、監察人資格限制，為何？（10 分）",
      "sourceIds": [
        "law-02",
        "law-01"
      ],
      "kind": "申論題",
      "answer": [
        "公司法對董事、監察人的資格外限主要是第30條消極資格（破產、詐欺、背信、侵占等）、行為能力及第192條選任資格；證交法對公開發行公司另有更嚴格的治理與股權限制：",
        "一、證交法第26條：全體董事及監察人持有記名股票股份總額不得低於公司已發行股份總額一定成數，具體成數由主管機關定之。二、第26條之3：公開發行公司董事會設董事不得少於5人；政府或法人股東代表人不得同時當選或擔任董事及監察人；董事間應有超過半數席次不得具有配偶或二親等以內親屬關係；監察人間或監察人與董事間應至少一席不具此關係；違反時依規定決定當選名單。",
        "三、第25條持股申報、第22條之2轉讓限制、第157條短線交易、第157條之1內線交易等，雖非「資格」本身，但構成公開發行公司董事、監察人的行為限制。",
        "四、獨立董事另適用證交法第14條之2的專業、獨立性與持股兼職限制；本題非獨立董事不適用該條，但仍受上述規範。"
      ],
