        "例外：一、股東未繳足股款或資本不實，應補繳並可能負賠償責任。二、公司法第154條第2項「揭開公司面紗」：股東濫用公司法人地位，致公司負擔特定債務且清償顯有困難，情節重大者，該股東應負清償責任。三、公司法第8條第3項實質董事/影子董事，與董事同負責任。四、公司設立登記虛偽、股東詐欺債權人等情形，依公司法第9條、民法第184條等負責。",
        "因此有限責任是原則，但不得用來詐害債權人或規避法定義務。"
