      "number": 1,
      "stem": "公司董事負有善良管理人之注意義務和忠實義務，為履行其受託人義務，董事應出席董事會。請問現行 公司法中，董事除親自出席董事會外，如當天無法現場出席，是否還有其他方式可以參與董事會？(10 分)",
