      "year": 109,
      "session": 4,
      "subject": "law",
      "number": 2,
      "stem": "為善盡公司之社會責任，A 上市公司(下稱 A 公司)擬捐贈新台幣一億元給相關機構作為 COVID-19 疫苗之研究經費，請問此一捐贈之決策應由何人/機關決定(5 分)？又 A 公司股東認為 A 公司此舉 侵害股東的權益，請問公司法是否有明文規定 A 公司可以考慮股東以外其他利害關係人(如員工、 消費者、社會等)之利益(5 分)？",
