      "answer": [
        "(1) 捐贈決策機關：原則上依公司法第202條由董事會決議，因為捐贈屬於公司業務執行事項，除法律、章程或股東會決議保留者外，由董事會決定。若捐贈金額達到公司法第185條第1項所稱「讓與全部或主要部分之營業或財產」的程度，則應經股東會特別決議；公司亦可於章程或內部治理程序把重大捐贈保留給股東會。A為上市公司，並應依證交法及公司治理實務辦理董事會/審計委員會審議與資訊揭露。",
        "(2) 公司法第1條第2項明文：「公司經營業務，應遵守法令及商業倫理規範，得採行增進公共利益之行為，以善盡其社會責任。」因此公司可以考量股東以外之員工、消費者、社會、環境等利害關係人利益；董事依第23條仍負忠實義務與善良管理人注意義務，但CSR條款提供董事會在商業判斷下平衡多元利益的依據。",
        "股東若認為捐贈侵害權益，可依公司法第194條請求董事會停止違法行為、第214條提起代表訴訟，或依第23條請求賠償；但若程序合法、金額合理且與公司長期利益/CSR相符，法院通常尊重董事會商業判斷。"
      ],
      "answerType": "reference",
      "note": "本站參考解答（非官方）"
