        "(一) 提案程序：依公司法第172條之1，持有已發行股份總數1%以上股份之股東，得向公司提出股東常會議案，但以一項為限、300字以內，並應在公司公告的受理期間內以書面或電子方式提出。提案股東應親自或委託他人出席股東常會並參與討論。董事會除有該條所列事由（非股東會權限、持股不足、逾期、超過字數或項數）外，應將議案列入議程，並在召集通知前通知處理結果。",
