      "stem": "A 上市公司(下稱 A 公司)從事綠電儲能相關設備之製造與銷售。A 公司投資於 B 非公開發行 公司（下稱 B 公司），持有B 公司 100％股權。A 公司總經理甲於 2017 年指示 B 公司董事長 乙與 C 非公開發行公司（下稱 C 公司）簽訂經銷契約，約定無論銷售額多寡，B 公司均須支 付 C 公司每年新台幣 （下同）600 萬元之酬金，自2017 年 7 月 1 日起為期五年。經查C 公司 於 2017 年至 2022 年，均無任何協助B 公司銷售之行為，且C 公司董事長丙為甲之配偶。請 根據證券交易法之規定，分析甲要求B 公司簽訂該經銷契約是否合法，是否有法律上責任？ （10 分）",
