        "證交法第171條第1項第2款規定，董事、監察人、經理人以直接或間接方式，使公司為不利益之交易，且不合營業常規，致公司遭受重大損害者，處3年以上10年以下有期徒刑，得併科新臺幣1,000萬元以上2億元以下罰金。甲透過B簽約，屬於間接使A集團為不利益交易；損害達3,000萬元，難謂非重大。",
