      "session": 2,
      "subject": "law",
      "number": 3,
      "stem": "A 公司於2020 年 3 月完成登錄為興櫃公司，實收資本新台幣（下同）2 億元。無奈經過一年 後，因為疫情影響，A 公司財務發生嚴重虧損，共計虧損 1 億 4 仟萬元，且公司資產已經不 足抵償負債。你是A 公司獨立董事，在不希望聲請公司破產，且能繼續維持營運之前提下，請問A 公司應立即採取哪些措施，始符合公司法之規範？（10 分）",
