        "同時應停止不當交易、保全帳冊與資產、揭露重大訊息，必要時引進策略投資人、辦理減資彌補虧損或債務協商；但這些措施不能取代第211條的報告與破產或重整程序。獨立董事若發現董事會怠於執行，應依公司法第218條之2請求停止違法行為，並保留書面紀錄。"
