      "sessionId": "112Q1",
      "year": 112,
      "session": 1,
      "subject": "law",
      "number": 1,
      "stem": "請簡述我國因 2020 年開始蔓延的 COVID-19 疫情，目前公司召集視訊股東會議之公司法、 證交法二法修正與因應。(10 分)",
