        "(一) 公司法第172條之2（110年12月29日修正公布）：公司章程得訂明股東會以視訊會議或其他經中央主管機關公告之方式召開；因天災、事變或其他不可抗力情事，中央主管機關得公告公司於一定期間內，得不經章程訂明，以視訊會議或其公告之方式開會。股東以視訊參與會議者，視為親自出席。公開發行股票公司之適用條件、作業程序及其他應遵行事項，證券主管機關另有規定者，從其規定。",
        "(二) 證券交易法第22條之1第2項（111年11月30日修正公布）：公開發行股票公司召開股東會、股東會視訊會議、書面或電子方式行使表決權、股務事務等，其應符合之條件、作業程序及其他應遵行事項，由主管機關定之。金管會並訂定「公開發行公司股東會視訊會議辦法」，規範視訊平台、身分驗證、會議登記、測試、表決、錄音錄影、資訊揭露等事項。",
        "(三) 因應：疫情期間金管會放寬公開發行公司得採視訊股東會，公司應依章程或主管機關公告辦理，並確保股東參與、表決與救濟權利不因視訊而受損；疫情後回歸常態，公司如要以視訊會議召開股東會，原則上應先修正章程訂明，公開發行公司並應符合金管會視訊會議辦法。"
