      "sessionId": "112Q1",
      "year": 112,
      "session": 1,
      "subject": "law",
      "number": 2,
      "stem": "請簡述我國企業私募公司債的公司法、證交法間之差異何在。(10 分)",
      "sourceIds": [
        "law-02"
      ],
      "kind": "申論題",
      "answer": [
        "(一) 公司法之私募公司債：依公司法第248條第2項，普通公司債、轉換公司債或附認股權公司債之私募，不受第249條第2款及第250條第2款限制，並應於發行後15日內檢附相關資料向證券主管機關報備；私募之發行公司不以上市、上櫃或公開發行公司為限。私募人數不得超過35人，但金融機構應募者不在此限。普通公司債之私募原則上經董事會決議；轉換公司債或附認股權公司債依第248條之1，應經董事會決議及股東會決議。",
        "(二) 證券交易法之私募：公開發行公司依第43條之6私募有價證券，應經代表已發行股份總數過半數股東出席、出席股東表決權三分之二以上同意；應募人限於銀行、票券、信託、保險、證券等法人或機構、符合主管機關所定條件之自然人、法人或基金，以及公司或關係企業之董事、監察人、經理人；其中第二、三類應募人合計不得超過35人。普通公司債私募總額，除經主管機關徵詢目的事業主管機關同意者外，不得逾全部資產減去全部負債餘額之400%，不受公司法第247條限制，並得於董事會決議日起一年內分次辦理；價款繳納完成後15日內報請主管機關備查。",
        "(三) 主要差異：公司法適用所有公司，程序上普通公司債以董事會決議為主，轉換公司債及附認股權公司債才需股東會決議；證交法僅適用公開發行公司，所有私募原則上均須股東會特別決議，且對應募人類型、人數、總額、資訊揭露與轉讓限制有較嚴格規範。證交法並禁止一般性廣告或公開勸誘，私募有價證券轉讓受第43條之8限制；公司法私募則無相同轉讓限制。"
      ],
      "answerType": "reference",
