      "kind": "申論題",
      "answer": [
        "公司法第157條第1項列舉八款特別股事項，第3項則規定公開發行股票公司不得發行下列特別股：第一項第4款（複數表決權特別股、對於特定事項具否決權特別股）、第5款（特別股股東被選舉為董事、監察人之禁止或限制，或當選一定名額董事之權利）、第7款（特別股轉讓之限制），以及得轉換成複數普通股之特別股。",
        "因此上市櫃公司得發行的特別股包括：一、股息及紅利分派順序、定額或定率之特別股（第1款）。二、剩餘財產分派順序、定額或定率之特別股（第2款）。三、表決權行使順序、限制或無表決權之特別股（第3款），但不得為複數表決權或對特定事項否決權。四、得轉換成普通股之特別股（第6款），但不得轉換成複數普通股。五、其他權利義務事項之特別股（第8款）。",
        "簡言之，上市櫃公司可以發行優先分派股息、優先分派剩餘財產、表決權受限或無表決權、可轉換普通股（非複數）及其他不違反強制規定的特別股；不得發行複數表決權、特定事項否決權、董監選舉特權、轉讓限制及轉換複數普通股的特別股。"
      ],
      "answerType": "reference",
      "note": "本站參考解答（非官方）"
