      "year": 113,
      "session": 2,
      "subject": "law",
      "number": 2,
      "stem": "甲為A 上市公司之一般董事，為執行業務之需要，擬向公司請求查閱、抄錄或複製公司業務、財務狀況 及簿冊文件等資訊。試說明董事甲行使資訊請求權之法律基礎為何？(10 分)",
