        "(一) 法律基礎：首先，公司法第202條規定，公司業務之執行，除本法或章程規定應由股東會決議者外，均應由董事會決議行之；董事為董事會成員，為執行職務必須取得充分資訊。其次，公司法第23條第1項規定，董事為公司負責人，應忠實執行業務並盡善良管理人之注意義務；若未取得必要資訊即作成決策，可能違反忠實義務與注意義務。公司法第8條亦明定董事為公司負責人。",
        "(二) 實務法理：最高法院110年度台上字第3245號、111年度台上字第1079號等判決承認，董事為執行業務，於必要範圍內得請求公司提供業務、財務狀況及簿冊文件，公司不得無正當理由拒絕；經濟部函釋亦認為董事查閱範圍不宜過度限制。其法理是董事會職權與董事忠實義務的附隨權能，而不是股東權的延伸。",
        "(三) 明文爭議：公司法第210條第2項僅賦予股東及公司債權人檢具利害關係證明文件、指定範圍查閱、抄錄或複製章程及簿冊的權利，不能直接作為董事資訊請求權的依據。2018年公司法修正草案曾擬增訂第193條之1明定董事查閱權，但未完成立法；現行第193條之1是董事責任保險，與資訊請求權無關。",
        "(四) 範圍與限制：甲的請求應以執行董事職務所必要者為限，並負保密義務；公司如有營業秘密、董事與公司利益衝突、權利濫用、查閱成本過高等正當理由，得限制或拒絕。結論：甲有資訊請求權，法律基礎為公司法第202條的董事會職權、第23條的忠實義務與實務判決法理，公司無正當理由不得拒絕。"
