      "year": 113,
      "session": 3,
      "subject": "law",
      "number": 1,
      "stem": "試問公司年度盈餘分派員工酬勞，公司法與證券交易法的規定分別為何？",
      "sourceIds": [
        "law-02"
      ],
      "kind": "申論題",
      "answer": [
        "(一) 公司法第235條之1：公司應於章程訂明以當年度獲利狀況之定額或比率，分派員工酬勞；公司尚有累積虧損時，應先予彌補。員工酬勞以股票或現金為之，應由董事會以董事三分之二以上之出席及出席董事過半數同意之決議行之，並報告股東會。章程得訂明發給股票或現金之對象，包括符合一定條件之控制或從屬公司員工。",
        "(二) 證券交易法第14條第6項（113年8月7日修正公布）：股票已在證券交易所上市或於證券櫃檯買賣中心上櫃買賣之公司，應於章程訂明以年度盈餘提撥一定比率為基層員工調整薪資或分派酬勞；公司尚有累積虧損時，應予彌補。基層員工指非屬經理人且薪資水準低於一定金額者；該比率得於公司法第235條之1第1項員工酬勞範圍內定之，並得以固定數、一定區間或下限方式訂定。",
        "(三) 證交法第14條第7項並規定，前項調整薪資或分派酬勞之金額，得自當年度營利事業所得額減除。金管會要求上市櫃公司於114年股東會完成章程修訂，114年度起適用。",
        "(四) 兩者區別：公司法適用所有公司，規範員工酬勞的一般法定程序與董事會特別決議；證交法僅適用上市櫃公司，額外要求以年度盈餘一定比率照顧基層員工，可選擇調整薪資或分派酬勞，或二者併行。"
      ],
      "answerType": "reference",
