        "公司債債權人會議：依公司法第263條，發行公司、受託人或同次公司債總數百分之五以上債權人得召集會議。決議應有代表公司債債權總額四分之三以上債權人出席，以出席債權人表決權三分之二以上同意行之，並按每一公司債券最低票面金額有一表決權。",
