        "主要不同在於：股東會以股份表決權計算，普通決議門檻為過半數出席、過半數同意，無須法院認可；公司債債權人會議以債權總額比例計算，出席門檻四分之三、同意門檻三分之二，且須經法院認可並公告後始對全體債權人發生效力。"
