      "year": 114,
      "session": 2,
      "subject": "law",
      "number": 2,
      "stem": "A 股份有限公司章程第 5 條規定：「本公司資本額訂為新臺幣 5,100 萬元，分為 5 萬 1,000 股，每股金額新臺幣 1,000 元，得分次發行。」若 A 公司之資本額歷經多年增資後，已全數發 行。惟近年來因經濟情勢惡化，已累積虧損新臺幣 3,000 萬元，若 A 公司擬減資以彌補虧損，其股東會應採用何種決議方法，其程序始合法？(10 分)",
