      "year": 114,
      "session": 2,
      "subject": "law",
      "number": 3,
      "stem": "A 上市公司設有 7 席董事，甲為董事長。其中乙、丙、丁三人為獨立董事，組成審計委員會，乙為審計委員會之召集人。若乙認為 A 公司之董事長甲有重大違法行為，應提請股東會將之決 議解任，乙遂自行召集股東臨時會，是否合法？(10 分)",
