        "若董事會不召集股東會，應依公司法由符合資格之股東、監察人或法院等法定召集程序處理，不能由獨立董事逕行召集。乙自行召集之會議，其召集程序不合法，會議決議可能不成立或被撤銷。",
        "解任董事長或董事，仍須經合法召集之股東會決議；審計委員會召集人之職權不能擴張為股東會召集權。"
