      "number": 2,
      "stem": "A 上市金融控股公司旗下有 A1 證券商(股份有限公司)，經查，A1 證券商為 A 金控百分之百 持有之子公司，此時 A1 證券商之股東會、董事會及監察人等內部機關，依據公司法有何特 殊性及得為何種設計？(10 分)",
